<script setup>import {ref,computed} from 'vue';import {media as defaults} from '../data.js';const load=()=>{try{return JSON.parse(localStorage.getItem('casil-media')||'null')||structuredClone(defaults)}catch{return structuredClone(defaults)}};const films=ref(load());const draft=ref(null);const save=()=>localStorage.setItem('casil-media',JSON.stringify(films.value));const featured=computed(()=>films.value.filter(x=>x.featured));function add(){const f={id:`film-${Date.now()}`,title:'New film',category:'Behind the Scenes',duration:'00:00',description:'Add a description.',thumbnail:'',video:'',featured:false};films.value.push(f);draft.value=f}function remove(f){films.value=films.value.filter(x=>x.id!==f.id);save()}function move(f,delta){const i=films.value.indexOf(f),j=i+delta;if(j<0||j>=films.value.length)return;[films.value[i],films.value[j]]=[films.value[j],films.value[i]];save()}function toggle(f){if(!f.featured&&featured.value.length>=6){alert('Choose up to six featured items.');return}f.featured=!f.featured;save()}function edit(){if(draft.value.featured&&films.value.filter(x=>x.featured&&x.id!==draft.value.id).length>=6){alert("Choose up to six featured items.");return}save();draft.value=null}</script><template><section class="page-hero"><span class="eyebrow">Media manager  |  demo mode</span><h1>Curate the<br/>moving image.</h1><p>Manage sample media records locally in this browser. The public featured section shows up to six items.</p></section><section class="section"><div class="notice">Browser-local demonstration only. Changes are stored in localStorage and are not shared or uploaded.</div><div class="manager-head"><h2>Media library <small>({{films.length}} records  |  {{featured.length}} featured)</small></h2><button class="button" @click="add">+ Add a video record</button></div><article v-for="(f,index) in films" :key="f.id" class="manager-row"><img :src="f.thumbnail||'/casil-shots.svg'" :alt="f.title"/><div class="manager-info"><span class="eyebrow">{{f.category}}  |  {{f.duration}} <b v-if="f.featured"> |  Featured</b></span><h3>{{f.title}}</h3><p>{{f.description}}</p></div><div class="manager-actions"><button @click="draft=f">Edit</button><button @click="move(f,-1)" :disabled="index===0" aria-label="Move up">UP</button><button @click="move(f,1)" :disabled="index===films.length-1" aria-label="Move down">DOWN</button><button @click="toggle(f)">{{f.featured?'Unfeature':'Feature'}}</button><button @click="remove(f)">Remove</button></div></article><div v-if="draft" class="edit-panel"><button class="close-edit" @click="draft=null">CLOSE</button><h2>Edit media record</h2><div class="form"><div class="field"><label>Title</label><input v-model="draft.title"/></div><div class="field"><label>Category</label><input v-model="draft.category"/></div><div class="field"><label>Duration</label><input v-model="draft.duration" placeholder="01:25"/></div><div class="field"><label>Thumbnail URL</label><input v-model="draft.thumbnail" placeholder="https://..."/></div><div class="field"><label>Working video URL (optional)</label><input v-model="draft.video" placeholder="https://..."/></div><div class="field"><label>Public featured slot</label><select v-model="draft.featured"><option :value="true">Featured</option><option :value="false">Not featured</option></select></div><div class="field full"><label>Description</label><textarea v-model="draft.description" rows="3"/></div><div class="field full"><button class="button" @click="edit">Save changes</button></div></div></div><p class="notice">Exactly six are shown initially. You can maintain other records in the library, reorder them, and select up to six for the public showcase.</p></section></template>
